    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa aspiración recurrente debe investigarse con pruebas de función deglutoria y evaluación de la fuerza neuromuscular. La cuantificación de inmunoglobulinas forma parte del estudio de inmunodeficiencias, no de aspiración.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- El estudio depende de la etiología sospechada.\r\n- La broncoscopia es útil en bronquiectasias focales.\r\n- La aspiración recurrente requiere evaluación de la deglución.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- **Bronquiectasia focal:**\r\n- Obstrucción (cuerpo extraño, tumor).\r\n- Estudios: radiografía/TC y broncoscopia.\r\n- **Bronquiectasia difusa:**\r\n- Infecciones → Gram, cultivos y BAAR.\r\n- Inmunodeficiencias → biometría hemática, inmunoglobulinas, VIH.\r\n- Causas genéticas → cloro en sudor, α1-antitripsina, estudios ciliares y pruebas genéticas.\r\n- **Enfermedades autoinmunitarias → exploración articular y serologías.**\r\n- Aspiración recurrente → evaluación de la deglución y fuerza neuromuscular.\r\n- Idiopática → estudio guiado por la clínica.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 290, cuadro 290-1.",
