    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl anticuerpo antineuronal se correlaciona, en algunas series, con lupus activo del sistema nervioso central cuando es positivo en el LCR, según el cuadro del Harrison.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Positividad en LCR.\r\n- Lupus activo del SNC.\r\n- Antígenos neuronales y linfocíticos de superficie.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- ANA: 98%; antígenos nucleares múltiples; mejor prueba de detección; inmunofluorescencia como prueba de referencia; alta sensibilidad y baja especificidad.\r\n- Anti-dsDNA: 70%; ADN bicatenario; específico de LES; se correlaciona con actividad, nefritis y vasculitis; inmunofluorescencia con Crithidia más específica que ELISA.\r\n- Anti-C1q: 33%; asociado con nefritis lúpica activa, especialmente junto con anti-dsDNA; no específico de LES.\r\n- Anti-Sm: 25%; específico de LES; sin correlación clínica definida.\r\n- Anti-RNP: 40%; no específico; asociado con síndromes reumáticos y firma génica inducida por IFN.\r\n- Anti-Ro (SS-A): 30%; síndrome seco, lupus cutáneo subagudo y lupus neonatal con bloqueo cardíaco congénito.\r\n- Anti-La (SS-B): 10%; casi siempre asociado con anti-Ro.\r\n- Antihistona: 70%; más frecuente en lupus inducido por fármacos.\r\n- Antifosfolípido: 50%; hipercoagulabilidad, abortos y trombocitopenia.\r\n- Antieritrocito: 60%; Coombs directa; hemólisis manifiesta.\r\n- Antiagregante plaquetario: 30%; relacionado con trombocitopenia; sin utilidad clínica suficiente.\r\n- Antineuronal: 60%; en algunas series se correlaciona con lupus activo del SNC.\r\n- Antirribosómico P: 20%; asociado con depresión o psicosis por lupus del SNC.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
