    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas manifestaciones neurológicas aparecen en aproximadamente el 60% de los pacientes. Dentro de ellas, los trastornos cognitivos (50%) constituyen la manifestación individual más frecuente.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Manifestaciones neurológicas: 60%.\r\n- Trastornos cognitivos: 50%.\r\n- Trastornos emocionales: 40%.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Neurológicas (60%): trastornos cognitivos (50%), trastornos emocionales (40%), depresión (25%), cefalea (25%), convulsiones (20%), mononeuropatía/polineuropatía (15%), ACV/isquemia transitoria (10%), confusión aguda o trastornos del movimiento (2–5%), meningitis aséptica o mielopatía (<1%).\r\n- Cardiopulmonares (60%): pleuritis, pericarditis o derrames (30–50%), miocarditis/endocarditis (10%), neumonitis lúpica (10%), coronariopatía (10%), fibrosis intersticial (5%), hipertensión pulmonar/SDRA/hemorragia (<5%), síndrome de encogimiento pulmonar (<5%).\r\n- Renales (30–50%): proteinuria >500 mg/24 h o cilindros celulares (30–60%), síndrome nefrótico (25%), nefropatía terminal (5–10%).\r\n- Digestivas (40%): síntomas inespecíficos (30%), enzimas hepáticas anómalas (40%), vasculitis (5%).\r\n- Trombosis: venosa (10%), arterial (5%).\r\n- Oculares (15%): síndrome de Sjögren (15%), conjuntivitis/epiescleritis (10%), vasculitis (5%).\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
