    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl cuadro destaca como efectos adversos del micofenolato la leucopenia, el linfoma y otros trastornos linfoproliferativos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Leucopenia.\r\n- Linfoma.\r\n- Trastornos linfoproliferativos.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Salicilatos/AINE: meningitis aséptica, insuficiencia renal, enzimas hepáticas elevadas, vasculitis cutánea; salicilatos: ototoxicidad y acúfenos.\r\n- Hidroxicloroquina: lesión retiniana, miocardiopatía, miopatía, neuropatía periférica, pigmentación cutánea, convulsiones, trombocitopenia; contraindicada con fármacos que prolongan el QT.\r\n- Metotrexato: mielosupresión, hepatotoxicidad, neumonitis, fibrosis pulmonar.\r\n- Ciclofosfamida: cistitis hemorrágica, carcinoma vesical, insuficiencia ovárica/testicular.\r\n- Micofenolato: leucopenia, linfoma, trastornos linfoproliferativos.\r\n- Azatioprina: pancreatitis y hepatotoxicidad.\r\n- Rituximab: infección (incluida LMP), reacciones a la infusión.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
