      "Sjögren: predominio en mujeres de mediana edad, presencia de autoanticuerpos e infiltración glandular por linfocitos T CD4+.",
      "Infección por VIH: granulomas en glándulas salivales, serología para VIH negativa y ausencia de preferencia por sexo.",
      "Sarcoidosis: relación con HLA-DR5, infiltración por linfocitos T CD8+ y serología para VIH positiva."
