    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl síndrome de Sjögren se caracteriza por predominio en mujeres de mediana edad, presencia de autoanticuerpos e infiltración linfoide de las glándulas salivales por linfocitos T CD4+. En cambio: La infección por VIH con síndrome seco predomina en varones jóvenes, presenta infiltración por linfocitos T CD8+ y serología para VIH positiva. La sarcoidosis no tiene preferencia por edad o sexo y muestra granulomas en las glándulas salivales.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Sjögren: mujeres de mediana edad, autoanticuerpos, T CD4+.\r\n- VIH con síndrome seco: varones jóvenes, T CD8+, serología positiva.\r\n- Sarcoidosis: granulomas salivales, sin preferencia por edad o sexo.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Infección por VIH y síndrome seco**\r\n- Predominio en varones jóvenes.\r\n- Ausencia de autoanticuerpos Ro/SS-A o La/SS-B.\r\n- Infiltración linfoide de glándulas salivales por linfocitos T CD8+.\r\n- Relación con HLA-DR5.\r\n- Serología para VIH positiva.\r\n\r\n**Síndrome de Sjögren**\r\n- Predominio en mujeres de mediana edad.\r\n- Presencia de autoanticuerpos.\r\n- Infiltración linfoide de glándulas salivales por linfocitos T CD4+.\r\n- Vinculación con HLA-DR3 y DRw52.\r\n- Serología para VIH negativa.\r\n\r\n**Sarcoidosis**\r\n- Sin preferencia por edad o sexo.\r\n- Ausencia de autoanticuerpos Ro/SS-A o La/SS-B.\r\n- Granulomas en las glándulas salivales.\r\n- Asociación con HLA desconocida.\r\n- Serología para VIH negativa.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 361. Cuadro 361-3. Diagnóstico diferencial del síndrome de Sjögren.",
