    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa secuencia STIR es sensible para detectar edema de la médula ósea, un hallazgo de inflamación activa en las articulaciones sacroilíacas. Por ello, resulta especialmente útil en pacientes con espondiloartritis axial no radiográfica, en quienes la radiografía puede ser normal o mostrar cambios mínimos. La secuencia T1 permite reconocer mejor lesiones estructurales, como erosiones corticales y cambios grasos subcondrales, pero no es la secuencia principal para demostrar edema activo.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- STIR: edema de médula ósea.\r\n- T1: erosiones corticales y grasa subcondral.\r\n- Radiografía normal no excluye enfermedad temprana.\r\n- La resonancia magnética detecta inflamación activa antes que la radiografía.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Hallazgos por imágenes en espondiloartritis axial**\r\n\r\n**Radiografía de pelvis**\r\n- Puede ser normal en la espondiloartritis axial no radiográfica.\r\n- Puede mostrar esclerosis mínima de las articulaciones sacroilíacas.\r\n\r\n**En enfermedad avanzada:**\r\n- Esclerosis.\r\n- Erosiones.\r\n- Fusión parcial o completa.\r\n- Sacroilitis bilateral.\r\n- Resonancia magnética T1\r\n- Erosión cortical.\r\n- Grasa subcondral.\r\n- Cambios estructurales crónicos.\r\n\r\n**Resonancia magnética STIR**\r\n- Edema de médula ósea.\r\n- Inflamación activa de las articulaciones sacroilíacas.\r\n\r\n**Columna vertebral**\r\n- Lesiones de Romanus o “esquinas brillantes”.\r\n- Sindesmofitos marginales.\r\n- Puentes óseos entre cuerpos vertebrales.\r\n- Anquilosis de articulaciones facetarias.\r\n- Columna en bambú en fases avanzadas.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Figura 362-1. Imágenes de espondiloartritis axial no radiográfica y espondilitis anquilosante.",
