    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLos sindesmofitos de la espondilitis anquilosante se forman por inflamación y posterior osificación en la unión del anillo fibroso con el cuerpo vertebral. Crecen en dirección vertical y pueden unir cuerpos vertebrales adyacentes, originando puentes óseos. No deben confundirse con los osteofitos degenerativos, que suelen ser más gruesos, de orientación horizontal u oblicua y no representan el patrón típico de la espondilitis anquilosante. Las lesiones de Romanus corresponden a erosión e inflamación en las esquinas vertebrales. Posteriormente pueden producir esclerosis y la imagen conocida como “esquinas brillantes”.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Sindesmofito: crecimiento óseo vertical marginal.\r\n- Lesión de Romanus: erosión de la esquina vertebral.\r\n- Columna en bambú: puentes óseos múltiples.\r\n- Puede coexistir anquilosis facetaria.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Evolución vertebral de la espondilitis anquilosante\r\n- Inflamación en la unión entre el anillo fibroso y el cuerpo vertebral.\r\n- Erosión del borde vertebral.\r\n- Reparación con tejido fibroso y hueso.\r\n- Formación de sindesmofitos marginales.\r\n- Unión en puente de cuerpos vertebrales vecinos.\r\n- Desarrollo progresivo de columna en bambú.\r\n\r\n**Otros hallazgos**\r\n- Lesiones de Romanus.\r\n- Osteoporosis difusa.\r\n- Erosión de cuerpos vertebrales.\r\n- Inflamación y destrucción de la unión disco-vertebral.\r\n- Artritis de articulaciones facetarias.\r\n- Anquilosis ósea facetaria.\r\n- Disminución precoz de la densidad mineral ósea.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Figura 362-1. Imágenes de espondiloartritis axial no radiográfica y espondilitis anquilosante.",
