    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLos antiinflamatorios no esteroideos son el tratamiento farmacológico de primera línea porque disminuyen el dolor espontáneo y a la palpación y mejoran la movilidad. Además, todo paciente debe realizar un programa de ejercicios orientado a conservar la postura y los arcos de movimiento. Si persiste actividad de la enfermedad pese al tratamiento adecuado, pueden utilizarse fármacos biológicos, principalmente inhibidores del TNF o de IL-17.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Medida básica: ejercicio y conservación de la postura.\r\n- Primera línea farmacológica: antiinflamatorios no esteroideos.\r\n- Enfermedad persistente: anti-TNF o anti-IL-17.\r\n- Sulfasalazina: principalmente artritis periférica.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Tratamiento de la espondilitis anquilosante**\r\n- Todos los pacientes: ejercicios para conservar postura y movilidad.\r\n- Primera línea: antiinflamatorios no esteroideos.\r\n- Actividad persistente: inhibidores del TNF.\r\n- Alternativa biológica: secukinumab o ixekizumab, dirigidos contra IL-17A.\r\n- Artritis periférica: sulfasalazina.\r\n- Sin beneficio demostrado: metotrexato y glucocorticoides orales.\r\n- Inhibidores de JAK: eficaces en estudios clínicos.\r\n- Cirugía: artroplastia total de cadera en artritis coxofemoral grave.\r\n- Uveítis: glucocorticoides locales y fármacos midriáticos.\r\n- Antes de iniciar anti-TNF: descartar tuberculosis latente y hepatitis B.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Tratamiento: espondilitis anquilosante.\r\n- regunta 1",
