    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa artritis reactiva es fundamentalmente un diagnóstico clínico. Debe sospecharse ante artritis o tendinitis aguda, inflamatoria, asimétrica y aditiva, con antecedente de infección previa y posibles manifestaciones extraarticulares. El análisis del líquido sinovial sirve sobre todo para excluir artritis séptica o por cristales. El HLA-B27 tiene escaso valor predictivo negativo, aunque puede aportar información pronóstica y ser útil en casos atípicos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Diagnóstico clínico.\r\n- No hay prueba confirmatoria definitiva.\r\n- Líquido sinovial: descartar sepsis o cristales.\r\n- HLA-B27: valor pronóstico, no excluyente.\r\n- Buscar antecedente infeccioso y manifestaciones extraarticulares.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Diagnóstico de artritis reactiva**\r\n\r\n**Sospechar ante artritis o tendinitis:**\r\n- Aguda.\r\n- Inflamatoria.\r\n- Asimétrica.\r\n- Aditiva.\r\n- Interrogar sobre infección previa, incluso asintomática.\r\n- Explorar ojos, mucosas, piel, uñas y genitales.\r\n\r\n**Líquido sinovial:**\r\n- descarta artritis séptica;\r\n- descarta artritis por cristales.\r\n- Cultivo, serología o pruebas moleculares pueden detectar infección inductora.\r\n\r\n**HLA-B27:**\r\n- escaso valor predictivo negativo;\r\n- útil en casos atípicos;\r\n- aporta información sobre gravedad, cronicidad, espondilitis y uveítis.\r\n- Considerar prueba para VIH.\r\n\r\n**Diferenciar de:**\r\n- enfermedad gonocócica diseminada;\r\n- artropatía psoriásica.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Artritis reactiva: Diagnóstico.",
