    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa combinación de psoriasis, dactilitis, afectación de articulaciones interfalángicas distales, cambios ungueales y artritis asimétrica es característica de artritis psoriásica.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Psoriasis previa o concomitante.\r\n- Dactilitis.\r\n- Afectación de articulaciones interfalángicas distales.\r\n- Cambios ungueales.\r\n- Artritis asimétrica.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Manifestaciones clínicas principales**\r\n- Psoriasis precede a la artritis en 70%.\r\n- Ambas aparecen con menos de un año de diferencia en 15%.\r\n- La artritis precede a la psoriasis en 15%.\r\n- Edad promedio de inicio: 37 años.\r\n- Dactilitis: >30%.\r\n- Entesitis y tenosinovitis frecuentes.\r\n- Cambios ungueales frecuentes.\r\n- Puede haber afectación periférica o axial.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Artritis psoriásica: Manifestaciones clínicas.",
