    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl signo histopatológico definitorio de la granulomatosis con poliangitis es la vasculitis necrosante de arterias y venas de pequeño calibre, acompañada de formación de granulomas intra o extravasculares. En el pulmón puede observarse necrosis geográfica rodeada por histiocitos y células gigantes. Las lesiones de las vías respiratorias altas muestran inflamación, necrosis y granulomas, con vasculitis variable.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Pensar en granulomatosis con poliangitis ante:**\r\n- vías aéreas superiores;\r\n- vías aéreas inferiores;\r\n- afectación renal.\r\n- Histología: vasculitis granulomatosa necrosante.\r\n- Vasos pequeños.\r\n- Granulomas intra o extravasculares.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Hallazgos patológicos principales**\r\n- Vasculitis necrosante de arterias y venas pequeñas.\r\n- Granulomas intra o extravasculares.\r\n- Pulmón: infiltrados nodulares múltiples y cavitados.\r\n- Vías respiratorias altas: inflamación, necrosis y granulomas.\r\n- Riñón: glomerulonefritis focal y segmentaria que puede evolucionar rápidamente.\r\n- Ausencia de depósitos de complejos inmunitarios en la lesión renal.\r\n- Granulomas renales poco frecuentes.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363. Granulomatosis con poliangitis: Histopatología y patogenia. Figura 363-2. Imagen histológica del pulmón en la granulomatosis con poliangitis.",
    "materia": "Medicina Interna",
