    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl ANCA contra proteinasa 3 (PR3) posee una alta especificidad para la granulomatosis con poliangitis, sobre todo cuando existe glomerulonefritis activa. Sin embargo, el texto enfatiza que su presencia es complementaria y no sustituye el diagnóstico histopatológico.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- ANCA-PR3.\r\n- Alta especificidad.\r\n- Complementa el diagnóstico.\r\n- No reemplaza la biopsia.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Diagnóstico**\r\n- Biopsia: método diagnóstico definitivo.\r\n- Pulmón: mayor rendimiento diagnóstico.\r\n- Vías respiratorias altas: inflamación granulomatosa con necrosis.\r\n- Riñón: glomerulonefritis paucinmunitaria.\r\n- ANCA contra PR3: alta especificidad, especialmente con glomerulonefritis activa.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363. Granulomatosis con poliangitis: Diagnóstico.",
