    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nAunque el ANCA contra PR3 tiene una elevada especificidad, no reemplaza el diagnóstico histopatológico. La biopsia continúa siendo el método diagnóstico definitivo.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Biopsia = diagnóstico definitivo.\r\n- ANCA-PR3 = apoyo diagnóstico.\r\n- Pulmón = mayor rendimiento.\r\n- Riñón = glomerulonefritis paucinmunitaria.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Diagnóstico diferencial y confirmación**\r\n- Confirmación mediante biopsia.\r\n- Biopsia pulmonar: mayor rendimiento.\r\n- Biopsia de vías respiratorias altas: inflamación granulomatosa con necrosis.\r\n- Biopsia renal: glomerulonefritis paucinmunitaria.\r\n- ANCA-PR3: complemento diagnóstico.\r\n\r\n**Diagnóstico diferencial:**\r\n- Síndrome de Goodpasture.\r\n- Policondritis recidivante.\r\n- Tumores de vías respiratorias altas o pulmón.\r\n- Histoplasmosis.\r\n- Endocarditis.\r\n- Leishmaniasis mucocutánea.\r\n- Rinoescleroma.\r\n- Enfermedades granulomatosas no infecciosas.\r\n- 📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363. Granulomatosis con poliangitis: Diagnóstico.",
